@@ -0,0 +1,103 @@
+import { mount } from "@vue/test-utils";
+import { describe, expect, test } from "vitest";
+import { createVuetify } from "vuetify";
+import { VNumberInput } from "vuetify/components/VNumberInput";
+import CookTime from "./CookTime.vue";
+
+const vuetify = createVuetify({ components: { VNumberInput } });
+
+function mountCookTime(modelValue: number | null, isEditMode = true) {
+  return mount(CookTime, {
+    props: { modelValue, isEditMode },
+    global: { plugins: [vuetify] },
+  });
+}
+
+async function type(wrapper: ReturnType<typeof mountCookTime>, value: string) {
+  const input = wrapper.find("input");
+  await input.setValue(value);
+}
+
+describe("CookTime", () => {
+  test("mounting emits nothing and null is blank", () => {
+    const wrapper = mountCookTime(null);
+    expect(wrapper.emitted("update:modelValue")).toBeUndefined();
+    expect(wrapper.findAll("input")).toHaveLength(1);
+    expect(wrapper.find("input").element.value).toBe("");
+    expect(wrapper.find("input").attributes("placeholder")).toBe("Minutes");
+  });
+
+  test.each([
+    ["60", 3600],
+    ["42", 2520],
+    ["35791394", 2147483640],
+  ])("typing %s emits %i seconds", async (text, seconds) => {
+    const wrapper = mountCookTime(null);
+    await type(wrapper, text);
+    expect(wrapper.emitted("update:modelValue")?.at(-1)).toEqual([seconds]);
+  });
+
+  test("clearing emits null", async () => {
+    const wrapper = mountCookTime(120);
+    await type(wrapper, "");
+    expect(wrapper.emitted("update:modelValue")?.at(-1)).toEqual([null]);
+  });
+
+  test("0 emits null and keeps showing 0", async () => {
+    const wrapper = mountCookTime(null);
+    await type(wrapper, "0");
+    expect(wrapper.emitted("update:modelValue")?.at(-1)).toEqual([null]);
+    await wrapper.setProps({ modelValue: null });
+    expect(wrapper.find("input").element.value).toBe("0");
+  });
+
+  test("minus keypress is prevented", async () => {
+    const wrapper = mountCookTime(null);
+    const event = new KeyboardEvent("keydown", { key: "-", cancelable: true, bubbles: true });
+    wrapper.find("input").element.dispatchEvent(event);
+    expect(event.defaultPrevented).toBe(true);
+  });
+
+  test("external changes show floor minutes", async () => {
+    const wrapper = mountCookTime(null);
+    await wrapper.setProps({ modelValue: 120 });
+    expect(wrapper.find("input").element.value).toBe("2");
+    await wrapper.setProps({ modelValue: 1 });
+    expect(wrapper.find("input").element.value).toBe("0");
+  });
+
+  test.each([1, 61, 3661, 2147483647])("leftover seconds %i show a hint", (seconds) => {
+    const wrapper = mountCookTime(seconds);
+    expect(wrapper.text()).toContain("Saved duration:");
+  });
+
+  test("whole minutes show no hint", () => {
+    expect(mountCookTime(120).text()).not.toContain("Saved duration:");
+  });
+
+  test("blur without change emits nothing; typing replaces exact seconds", async () => {
+    const wrapper = mountCookTime(90);
+    await wrapper.find("input").trigger("focus");
+    await wrapper.find("input").trigger("blur");
+    expect(wrapper.emitted("update:modelValue")).toBeUndefined();
+    await type(wrapper, "2");
+    expect(wrapper.emitted("update:modelValue")?.at(-1)).toEqual([120]);
+  });
+
+  test.each([
+    [3661, "1h 1m 1s"],
+    [90, "1m 30s"],
+    [60, "1m"],
+    [30, "30s"],
+  ])("display mode formats %i as %s", (seconds, text) => {
+    const wrapper = mountCookTime(seconds, false);
+    expect(wrapper.find("input").exists()).toBe(false);
+    expect(wrapper.text()).toBe(text);
+  });
+
+  test("display mode shows nothing for null", () => {
+    const wrapper = mountCookTime(null, false);
+    expect(wrapper.find("input").exists()).toBe(false);
+    expect(wrapper.text()).toBe("");
+  });
+});
