@@ -0,0 +1,109 @@
+<template>
+  <div v-if="isEditMode">
+    <v-number-input
+      :model-value="minutes"
+      :min="0"
+      :max="MAX_MINUTES"
+      :step="1"
+      :precision="0"
+      control-variant="hidden"
+      density="compact"
+      variant="outlined"
+      hide-details="auto"
+      :label="$t('recipe.step-duration-minutes')"
+      :placeholder="$t('recipe.step-duration-minutes')"
+      :hint="hint"
+      :persistent-hint="!!hint"
+      @keydown="onKeydown"
+      @update:model-value="onInput"
+    />
+  </div>
+  <span v-else-if="displayText">{{ displayText }}</span>
+</template>
+
+<script setup lang="ts">
+const MAX_MINUTES = 35791394; // 35791394 * 60 is the largest whole-minute value that fits a 32-bit integer
+
+const props = defineProps<{
+  modelValue: number | null;
+  isEditMode: boolean;
+}>();
+
+const emit = defineEmits<{
+  (e: "update:modelValue", value: number | null): void;
+}>();
+
+const { t } = useI18n();
+
+function formatDuration(totalSeconds: number | null | undefined): string {
+  if (!totalSeconds || totalSeconds <= 0) {
+    return "";
+  }
+  const h = Math.floor(totalSeconds / 3600);
+  const m = Math.floor((totalSeconds % 3600) / 60);
+  const s = totalSeconds % 60;
+  const parts: string[] = [];
+  if (h) parts.push(`${h}${t("recipe.step-duration-hours-abbr")}`);
+  if (m) parts.push(`${m}${t("recipe.step-duration-minutes-abbr")}`);
+  if (s) parts.push(`${s}${t("recipe.step-duration-seconds-abbr")}`);
+  return parts.join(" ");
+}
+
+function toMinutes(seconds: number | null): number | null {
+  return seconds == null ? null : Math.floor(seconds / 60);
+}
+
+const minutes = ref<number | null>(toMinutes(props.modelValue));
+let lastEmitted: number | null | undefined = undefined; // undefined: nothing emitted yet
+
+watch(() => props.modelValue, (incoming) => {
+  const isEcho = lastEmitted !== undefined && incoming === lastEmitted;
+  lastEmitted = undefined;
+  // typing "0" emits null; keep showing 0 when the parent hands that null back
+  if (isEcho && incoming === null && minutes.value === 0) {
+    return;
+  }
+  if (isEcho && incoming !== null) {
+    return;
+  }
+  minutes.value = toMinutes(incoming);
+});
+
+const displayText = computed(() => formatDuration(props.modelValue));
+
+const hint = computed(() => {
+  if (props.modelValue == null || props.modelValue % 60 === 0) {
+    return "";
+  }
+  return t("recipe.step-duration-saved", { duration: formatDuration(props.modelValue) });
+});
+
+function onKeydown(event: KeyboardEvent) {
+  if (event.key === "-") {
+    event.preventDefault();
+  }
+}
+
+function onInput(value: number | string | null | undefined) {
+  const parsed = typeof value === "string" ? (value.trim() === "" ? null : Number(value)) : value;
+  if (parsed == null || Number.isNaN(parsed)) {
+    commit(null, null);
+    return;
+  }
+  // blur/format passes the value we already show; only real edits emit
+  if (parsed === minutes.value) {
+    return;
+  }
+  const whole = Math.min(Math.max(Math.floor(parsed), 0), MAX_MINUTES);
+  commit(whole, whole === 0 ? null : whole * 60);
+}
+
+function commit(shown: number | null, seconds: number | null) {
+  if (shown === null && minutes.value === null && props.modelValue === null) {
+    return;
+  }
+  minutes.value = shown;
+  lastEmitted = seconds;
+  emit("update:modelValue", seconds);
+}
+</script>
