diff --git a/tests/integration_tests/user_recipe_tests/test_recipe_step_duration.py b/tests/integration_tests/user_recipe_tests/test_recipe_step_duration.py
new file mode 100644
index 0000000..b9148fd
--- /dev/null
+++ b/tests/integration_tests/user_recipe_tests/test_recipe_step_duration.py
@@ -0,0 +1,242 @@
+import io
+import json
+import zipfile
+from typing import Any
+
+import pytest
+from fastapi.testclient import TestClient
+from pydantic import ValidationError
+
+from tests.utils import api_routes
+from tests.utils.factories import random_string
+from tests.utils.fixture_schemas import TestUser
+
+
+def create_recipe(api_client: TestClient, user: TestUser) -> dict:
+    slug = api_client.post(api_routes.recipes, json={"name": random_string()}, headers=user.token).json()
+    return api_client.get(api_routes.recipes_slug(slug), headers=user.token).json()
+
+
+def put_steps(api_client: TestClient, user: TestUser, recipe: dict, steps: list[dict]):
+    body = {**recipe, "recipeInstructions": steps}
+    return api_client.put(api_routes.recipes_slug(recipe["slug"]), json=body, headers=user.token)
+
+
+def get_steps(api_client: TestClient, user: TestUser, slug: str) -> list[dict]:
+    response = api_client.get(api_routes.recipes_slug(slug), headers=user.token)
+    assert response.status_code == 200
+    return response.json()["recipeInstructions"]
+
+
+def summary(steps: list[dict]) -> list[tuple[str, Any]]:
+    return [(s["text"], s["durationSeconds"]) for s in steps]
+
+
+def test_put_then_get_returns_durations(api_client: TestClient, unique_user: TestUser):
+    recipe = create_recipe(api_client, unique_user)
+
+    r = put_steps(
+        api_client,
+        unique_user,
+        recipe,
+        [
+            {"text": "one", "durationSeconds": 90},
+            {"text": "two"},
+            {"text": "three", "durationSeconds": 2147483647},
+        ],
+    )
+    assert r.status_code == 200, r.text
+    assert summary(r.json()["recipeInstructions"]) == [("one", 90), ("two", None), ("three", 2147483647)]
+    assert summary(get_steps(api_client, unique_user, recipe["slug"])) == [
+        ("one", 90),
+        ("two", None),
+        ("three", 2147483647),
+    ]
+
+
+def test_put_is_idempotent_and_can_change_the_duration(api_client: TestClient, unique_user: TestUser):
+    recipe = create_recipe(api_client, unique_user)
+    first = put_steps(api_client, unique_user, recipe, [{"text": "one", "durationSeconds": 60}])
+    assert first.status_code == 200
+    step = get_steps(api_client, unique_user, recipe["slug"])[0]
+
+    for _ in range(2):
+        assert put_steps(api_client, unique_user, recipe, [step]).status_code == 200
+        assert summary(get_steps(api_client, unique_user, recipe["slug"])) == [("one", 60)]
+
+    assert put_steps(api_client, unique_user, recipe, [{**step, "durationSeconds": 3661}]).status_code == 200
+    assert summary(get_steps(api_client, unique_user, recipe["slug"])) == [("one", 3661)]
+
+
+@pytest.mark.parametrize("clear_with", [None, 0, "omit"])
+def test_put_clears_duration(api_client: TestClient, unique_user: TestUser, clear_with: Any):
+    recipe = create_recipe(api_client, unique_user)
+    assert put_steps(api_client, unique_user, recipe, [{"text": "keep", "durationSeconds": 42}]).status_code == 200
+    step = get_steps(api_client, unique_user, recipe["slug"])[0]
+    assert step["durationSeconds"] == 42
+
+    cleared = {k: v for k, v in step.items() if k != "durationSeconds"}
+    if clear_with != "omit":
+        cleared["durationSeconds"] = clear_with
+
+    r = put_steps(api_client, unique_user, recipe, [cleared])
+    assert r.status_code == 200, r.text
+
+    assert summary(get_steps(api_client, unique_user, recipe["slug"])) == [("keep", None)]
+
+
+INVALID_DURATIONS = [True, False, -1, 0.5, 2147483647.5, "90", "0", "PT1M", "", " ", 2147483648, 2147483648.0, 1e30]
+
+
+@pytest.mark.parametrize("invalid", INVALID_DURATIONS, ids=repr)
+def test_put_invalid_duration_is_rejected_and_nothing_changes(
+    api_client: TestClient, unique_user: TestUser, invalid: Any
+):
+    recipe = create_recipe(api_client, unique_user)
+    assert put_steps(api_client, unique_user, recipe, [{"text": "one", "durationSeconds": 90}]).status_code == 200
+    before = get_steps(api_client, unique_user, recipe["slug"])
+
+    r = put_steps(
+        api_client,
+        unique_user,
+        recipe,
+        [{"text": "changed", "durationSeconds": invalid}, {"text": "added"}],
+    )
+    assert r.status_code == 422
+    assert "durationSeconds" in json.dumps(r.json())
+
+    assert get_steps(api_client, unique_user, recipe["slug"]) == before
+
+
+@pytest.mark.parametrize("raw", ["NaN", "Infinity", "-Infinity"])
+def test_put_non_finite_duration_is_rejected(api_client: TestClient, unique_user: TestUser, raw: str):
+    recipe = create_recipe(api_client, unique_user)
+    before = get_steps(api_client, unique_user, recipe["slug"])
+    body = json.dumps({**recipe, "recipeInstructions": [{"text": "one", "durationSeconds": 7}]})
+    body = body.replace('"durationSeconds": 7', f'"durationSeconds": {raw}')
+
+    r = api_client.put(
+        api_routes.recipes_slug(recipe["slug"]),
+        content=body,
+        headers={**unique_user.token, "Content-Type": "application/json"},
+    )
+
+    assert r.status_code == 422
+    assert get_steps(api_client, unique_user, recipe["slug"]) == before
+
+
+def test_patch_sets_duration(api_client: TestClient, unique_user: TestUser):
+    recipe = create_recipe(api_client, unique_user)
+
+    r = api_client.patch(
+        api_routes.recipes_slug(recipe["slug"]),
+        json={"recipeInstructions": [{"text": "one", "durationSeconds": 120}]},
+        headers=unique_user.token,
+    )
+    assert r.status_code == 200, r.text
+    assert summary(get_steps(api_client, unique_user, recipe["slug"])) == [("one", 120)]
+
+    bad = api_client.patch(
+        api_routes.recipes_slug(recipe["slug"]),
+        json={"recipeInstructions": [{"text": "one", "durationSeconds": -5}]},
+        headers=unique_user.token,
+    )
+    assert bad.status_code == 422
+    assert summary(get_steps(api_client, unique_user, recipe["slug"])) == [("one", 120)]
+
+
+def test_requires_auth(api_client: TestClient, unique_user: TestUser):
+    recipe = create_recipe(api_client, unique_user)
+
+    r = api_client.put(
+        api_routes.recipes_slug(recipe["slug"]),
+        json={**recipe, "recipeInstructions": [{"text": "one", "durationSeconds": 5}]},
+    )
+
+    assert r.status_code == 401
+
+
+def populate(api_client: TestClient, user: TestUser) -> dict:
+    recipe = create_recipe(api_client, user)
+    r = put_steps(
+        api_client,
+        user,
+        recipe,
+        [{"text": "with", "durationSeconds": 3661}, {"text": "without"}, {"text": "minute", "durationSeconds": 60}],
+    )
+    assert r.status_code == 200, r.text
+    return api_client.get(api_routes.recipes_slug(recipe["slug"]), headers=user.token).json()
+
+
+def test_duplicate_retains_durations(api_client: TestClient, unique_user: TestUser):
+    original = populate(api_client, unique_user)
+
+    r = api_client.post(
+        api_routes.recipes_slug_duplicate(original["slug"]), json={"name": random_string()}, headers=unique_user.token
+    )
+    assert r.status_code == 201, r.text
+
+    duplicate = api_client.get(api_routes.recipes_slug(r.json()["slug"]), headers=unique_user.token).json()
+    assert duplicate["id"] != original["id"]
+    assert summary(duplicate["recipeInstructions"]) == [("with", 3661), ("without", None), ("minute", 60)]
+    assert {s["id"] for s in duplicate["recipeInstructions"]}.isdisjoint(
+        {s["id"] for s in original["recipeInstructions"]}
+    )
+
+    # the source recipe is untouched
+    assert summary(get_steps(api_client, unique_user, original["slug"])) == summary(original["recipeInstructions"])
+
+
