+import io
+from pathlib import Path
+from types import ModuleType
+
+import pytest
+import sqlalchemy as sa
+from alembic.config import Config
+from alembic.migration import MigrationContext
+from alembic.operations import Operations
+from alembic.script import ScriptDirectory
+
+import mealie.db.models._all_models  # noqa: F401
+from mealie.db.init_db import ALEMBIC_DIR
+from mealie.db.models._model_base import SqlAlchemyBase
+from tests.utils.alembic_reader import ALEMBIC_MIGRATIONS, import_file
+
+REVISION = "afdc42353aa4"
+DOWN_REVISION = "a91720b8a7e7"
+TABLE = "recipe_instructions"
+REF_TABLES = ("recipe_ingredient_ref_link", "recipe_note_ref_link")
+
+
+def _migration() -> ModuleType:
+    path = next(ALEMBIC_MIGRATIONS.glob(f"*{REVISION}*.py"))
+    return import_file("add_duration_to_recipe_steps", path)
+
+
+def test_migration_revision_ids() -> None:
+    module = _migration()
+
+    assert module.revision == REVISION
+    assert module.down_revision == DOWN_REVISION
+
+
+def test_migration_is_the_single_head() -> None:
+    config = Config()
+    config.set_main_option("script_location", str(ALEMBIC_DIR))
+
+    assert ScriptDirectory.from_config(config).get_heads() == [REVISION]
+
+
+@pytest.mark.parametrize("dialect", ["sqlite", "postgresql"])
+def test_upgrade_offline_sql_is_a_plain_nullable_add_column(dialect: str) -> None:
+    buffer = io.StringIO()
+    context = MigrationContext.configure(dialect_name=dialect, opts={"as_sql": True, "output_buffer": buffer})
+
+    with Operations.context(context):
+        _migration().upgrade()
+
+    sql = " ".join(buffer.getvalue().split())
+    assert "ALTER TABLE recipe_instructions ADD COLUMN duration_seconds INTEGER" in sql
+
+    for forbidden in ("NOT NULL", "DEFAULT", "UPDATE"):
+        assert forbidden not in sql.upper()
+    # no table rebuild for SQLite, it must stay a cheap in-place change
+    assert "CREATE TABLE" not in sql.upper()
+    assert "DROP TABLE" not in sql.upper()
+
+
+def _snapshot(engine: sa.Engine) -> dict:
+    """Everything about the step table and the tables that point at it that a rebuild could lose."""
+    inspector = sa.inspect(engine)
+
+    def table_state(name: str) -> dict:
+        return {
+            "indexes": sorted(
+                (ix["name"], tuple(ix["column_names"]), bool(ix["unique"])) for ix in inspector.get_indexes(name)
+            ),
+            "foreign_keys": sorted(
+                (tuple(fk["constrained_columns"]), fk["referred_table"], tuple(fk["referred_columns"]))
+                for fk in inspector.get_foreign_keys(name)
+            ),
+            "pk": inspector.get_pk_constraint(name)["constrained_columns"],
+        }
+
+    return {name: table_state(name) for name in (TABLE, *REF_TABLES)}
+
+
+def _columns(engine: sa.Engine) -> list[str]:
+    return [c["name"] for c in sa.inspect(engine).get_columns(TABLE)]
+
+
+def _run(engine: sa.Engine, direction: str) -> None:
+    with engine.begin() as connection:
+        with Operations.context(MigrationContext.configure(connection)):
+            getattr(_migration(), direction)()
+
+
+def _rows(engine: sa.Engine, sql: str) -> list[tuple]:
+    with engine.connect() as connection:
+        return [tuple(r) for r in connection.execute(sa.text(sql))]
+
+
+def test_upgrade_downgrade_upgrade_on_populated_sqlite(tmp_path: Path) -> None:
+    engine = sa.create_engine(f"sqlite:///{tmp_path / 'migration.db'}")
+    try:
+        # the model metadata is the schema at the head revision, duration_seconds included
+        SqlAlchemyBase.metadata.create_all(engine)
+        baseline = _snapshot(engine)
+        assert "duration_seconds" in _columns(engine)
+        assert {"position", "recipe_id"} <= {c for ix in baseline[TABLE]["indexes"] for c in ix[1]}
+        assert baseline["recipe_ingredient_ref_link"]["foreign_keys"] == [(("instruction_id",), TABLE, ("id",))]
+        assert baseline["recipe_note_ref_link"]["foreign_keys"] == [(("instruction_id",), TABLE, ("id",))]
+
+        with engine.begin() as connection:
+            for n in (1, 2):
+                connection.execute(
+                    sa.text(
+                        "INSERT INTO recipe_instructions (id, position, type, title, text, summary, duration_seconds) "
+                        "VALUES (:id, :pos, '', :title, :text, 's', :dur)"
+                    ),
+                    {"id": f"i{n}", "pos": n, "title": f"t{n}", "text": f"step {n}", "dur": 90 * n},
+                )
+            for table in REF_TABLES:
+                connection.execute(sa.text(f"INSERT INTO {table} (instruction_id, reference_id) VALUES ('i1', 'r1')"))
+
+        kept = "SELECT id, position, title, text, summary FROM recipe_instructions ORDER BY position"
+        expected_rows = [("i1", 1, "t1", "step 1", "s"), ("i2", 2, "t2", "step 2", "s")]
+
+        for _ in range(2):
+            _run(engine, "downgrade")
+            assert "duration_seconds" not in _columns(engine)
+            assert _rows(engine, kept) == expected_rows
+            for table in REF_TABLES:
+                assert _rows(engine, f"SELECT instruction_id, reference_id FROM {table}") == [("i1", "r1")]
+            # a rebuilt table must keep every index and foreign key
+            assert _snapshot(engine) == baseline
+
+            _run(engine, "upgrade")
+            assert "duration_seconds" in _columns(engine)
+            assert _rows(engine, kept) == expected_rows
+            # existing rows read back as NULL, nothing is backfilled
+            assert _rows(engine, "SELECT duration_seconds FROM recipe_instructions") == [(None,), (None,)]
+            assert _snapshot(engine) == baseline
+    finally:
+        engine.dispose()

