@@ -0,0 +1,106 @@
+<template>
+  <div class="cook-time">
+    <v-number-input
+      v-if="isEditMode"
+      :model-value="minutes"
+      :min="0"
+      :max="MAX_MINUTES"
+      :step="1"
+      :precision="0"
+      control-variant="hidden"
+      density="compact"
+      variant="outlined"
+      :placeholder="$t('recipe.cook-time-minutes')"
+      :aria-label="$t('recipe.cook-time-minutes')"
+      :hint="savedDurationHint"
+      persistent-hint
+      @update:model-value="onInput"
+      @keydown="onKeydown"
+    />
+    <span v-else-if="formatted" class="cook-time-display">{{ formatted }}</span>
+  </div>
+</template>
+
+<script setup lang="ts">
+import { computed, ref, watch } from "vue";
+
+const MAX_MINUTES = 35791394; // 35791394 * 60 = 2147483640, the largest whole-minute value that fits a 32-bit column
+
+const props = defineProps<{
+  modelValue: number | null;
+  isEditMode: boolean;
+}>();
+
+const emit = defineEmits<{
+  (e: "update:modelValue", value: number | null): void;
+}>();
+
+const i18n = useI18n();
+
+function toMinutes(seconds: number | null | undefined): number | null {
+  return seconds == null ? null : Math.floor(seconds / 60);
+}
+
+// The input's own state. It only ever changes from the user's typing or from an outside change of
+// modelValue, and it is never turned back into an emit by a watcher.
+const minutes = ref<number | null>(toMinutes(props.modelValue));
+// "0" is sent to the parent as null, which would blank the field again; this keeps the 0 on screen.
+const typedZero = ref(false);
+
+watch(() => props.modelValue, (value) => {
+  if (value == null && typedZero.value) {
+    return;
+  }
+  typedZero.value = false;
+  minutes.value = toMinutes(value);
+});
+
+function onInput(value: number | string | null) {
+  if (value === null || value === undefined || value === "") {
+    typedZero.value = false;
+    minutes.value = null;
+    emit("update:modelValue", null);
+    return;
+  }
+
+  const parsed = Math.floor(Number(value));
+  if (Number.isNaN(parsed)) {
+    return;
+  }
+
+  const clamped = Math.min(Math.max(parsed, 0), MAX_MINUTES);
+  minutes.value = clamped;
+  typedZero.value = clamped === 0;
+  emit("update:modelValue", clamped === 0 ? null : clamped * 60);
+}
+
+function onKeydown(event: KeyboardEvent) {
+  if (event.key === "-") {
+    event.preventDefault();
+  }
+}
+
+function formatDuration(totalSeconds: number | null | undefined): string {
+  if (totalSeconds == null || !Number.isFinite(totalSeconds) || totalSeconds <= 0) {
+    return "";
+  }
+  const hours = Math.floor(totalSeconds / 3600);
+  const mins = Math.floor((totalSeconds % 3600) / 60);
+  const secs = Math.floor(totalSeconds % 60);
+
+  const parts: string[] = [];
+  if (hours) parts.push(i18n.t("recipe.cook-time-hours-short", { count: hours }));
+  if (mins) parts.push(i18n.t("recipe.cook-time-minutes-short", { count: mins }));
+  if (secs) parts.push(i18n.t("recipe.cook-time-seconds-short", { count: secs }));
+  return parts.join(" ");
+}
+
+const formatted = computed(() => formatDuration(props.modelValue));
+
+const savedDurationHint = computed(() => {
+  if (props.modelValue == null || props.modelValue % 60 === 0) {
+    return undefined;
+  }
+  return i18n.t("recipe.cook-time-saved-duration", { duration: formatDuration(props.modelValue) });
+});
+</script>
