+import io
+import json
+import tempfile
+import zipfile
+from pathlib import Path
+
+import pytest
+from fastapi.testclient import TestClient
+
+from mealie.schema.recipe.recipe import Recipe
+from mealie.services.recipe.template_service import TemplateService
+from tests.utils import api_routes
+from tests.utils.factories import random_string
+from tests.utils.fixture_schemas import TestUser
+
+
+def _create_recipe(api_client: TestClient, user: TestUser, steps: list[dict]) -> dict:
+    slug = api_client.post(api_routes.recipes, json={"name": random_string()}, headers=user.token).json()
+    recipe = api_client.get(api_routes.recipes_slug(slug), headers=user.token).json()
+    recipe["recipeInstructions"] = steps
+    response = api_client.put(api_routes.recipes_slug(slug), json=recipe, headers=user.token)
+    assert response.status_code == 200, response.text
+    return api_client.get(api_routes.recipes_slug(slug), headers=user.token).json()
+
+
+def _put(api_client: TestClient, user: TestUser, recipe: dict):
+    return api_client.put(api_routes.recipes_slug(recipe["slug"]), json=recipe, headers=user.token)
+
+
+def _get(api_client: TestClient, user: TestUser, slug: str) -> dict:
+    response = api_client.get(api_routes.recipes_slug(slug), headers=user.token)
+    assert response.status_code == 200
+    return response.json()
+
+
+def _durations(recipe: dict) -> list:
+    return [s["durationSeconds"] for s in recipe["recipeInstructions"]]
+
+
+def test_put_get_change_and_clear_duration(api_client: TestClient, unique_user: TestUser) -> None:
+    recipe = _create_recipe(
+        api_client,
+        unique_user,
+        [
+            {"text": "chop", "durationSeconds": 3600},
+            {"text": "stir"},
+            {"text": "wait", "durationSeconds": None},
+            {"text": "float", "durationSeconds": 90.0},
+        ],
+    )
+    assert _durations(recipe) == [3600, None, None, 90]
+    assert isinstance(recipe["recipeInstructions"][3]["durationSeconds"], int)
+
+    # change
+    recipe["recipeInstructions"][0]["durationSeconds"] = 42
+    recipe["recipeInstructions"][1]["durationSeconds"] = 2147483647
+    assert _put(api_client, unique_user, recipe).status_code == 200
+    recipe = _get(api_client, unique_user, recipe["slug"])
+    assert _durations(recipe) == [42, 2147483647, None, 90]
+
+    # clear with null and with 0, texts are kept
+    recipe["recipeInstructions"][0]["durationSeconds"] = None
+    recipe["recipeInstructions"][3]["durationSeconds"] = 0
+    assert _put(api_client, unique_user, recipe).status_code == 200
+    recipe = _get(api_client, unique_user, recipe["slug"])
+    assert _durations(recipe) == [None, 2147483647, None, None]
+    assert [s["text"] for s in recipe["recipeInstructions"]] == ["chop", "stir", "wait", "float"]
+
+
+@pytest.mark.parametrize("bad", [True, False, -1, 0.5, 2147483648, 2147483648.0, 1e30, "90", "0", "PT1M", "", " "])
+def test_invalid_duration_is_422_and_not_saved(api_client: TestClient, unique_user: TestUser, bad) -> None:
+    recipe = _create_recipe(api_client, unique_user, [{"text": "chop", "durationSeconds": 60}])
+    stored = _get(api_client, unique_user, recipe["slug"])
+
+    recipe["recipeInstructions"][0]["durationSeconds"] = bad
+    recipe["recipeInstructions"][0]["text"] = "changed"
+    response = _put(api_client, unique_user, recipe)
+    assert response.status_code == 422
+
+    assert _get(api_client, unique_user, recipe["slug"]) == stored
+
+
+@pytest.mark.parametrize("token", ["NaN", "Infinity", "-Infinity"])
+def test_non_finite_duration_is_422(api_client: TestClient, unique_user: TestUser, token: str) -> None:
+    recipe = _create_recipe(api_client, unique_user, [{"text": "chop", "durationSeconds": 60}])
+    stored = _get(api_client, unique_user, recipe["slug"])
+
+    recipe["recipeInstructions"][0]["durationSeconds"] = "__TOKEN__"
+    body = json.dumps(recipe).replace('"__TOKEN__"', token)
+    response = api_client.put(
+        api_routes.recipes_slug(recipe["slug"]),
+        content=body,
+        headers={**unique_user.token, "Content-Type": "application/json"},
+    )
+    assert response.status_code == 422
+    assert _get(api_client, unique_user, recipe["slug"]) == stored
+
+
+def test_raw_export_and_zip_import_round_trip(api_client: TestClient, unique_user: TestUser) -> None:
+    recipe = _create_recipe(
+        api_client,
+        unique_user,
+        [{"text": "a", "durationSeconds": 3661}, {"text": "b"}, {"text": "c", "durationSeconds": 60}],
+    )
+
+    with tempfile.TemporaryDirectory() as tmp:
+        raw_path = TemplateService(Path(tmp)).render(Recipe(**recipe), "raw")
+        raw = json.loads(raw_path.read_text())
+    assert [s["durationSeconds"] for s in raw["recipeInstructions"]] == [3661, None, 60]
+
+    # the zip export template (snake case dump) also round trips
+    export = api_client.get(
+        api_routes.recipes_slug_exports(recipe["slug"]), params={"template_name": "zip"}, headers=unique_user.token
+    )
+    assert export.status_code == 200
+    with zipfile.ZipFile(io.BytesIO(export.content)) as zf:
+        zip_json = json.loads(zf.read(next(n for n in zf.namelist() if n.endswith(".json"))))
+    assert [s["duration_seconds"] for s in zip_json["recipe_instructions"]] == [3661, None, 60]
+
+    for payload in (raw, zip_json):
+        payload["name"] = random_string()
+        payload["slug"] = payload["name"]
+        buf = io.BytesIO()
+        with zipfile.ZipFile(buf, "w") as zf:
+            zf.writestr("recipe.json", json.dumps(payload))
+        buf.seek(0)
+        response = api_client.post(
+            api_routes.recipes_create_zip,
+            files={"archive": ("recipe.zip", buf, "application/zip")},
+            headers=unique_user.token,
+        )
+        assert response.status_code == 201, response.text
+        imported = _get(api_client, unique_user, response.json())
+        assert imported["id"] != recipe["id"]
+        assert _durations(imported) == [3661, None, 60]
+        assert [s["text"] for s in imported["recipeInstructions"]] == ["a", "b", "c"]
