+    + [2147483648.0, 1e30, -0.5, [], {}, b"1"],
+)
+def test_duration_rejected(value) -> None:
+    with pytest.raises(ValidationError):
+        RecipeStep(text="x", duration_seconds=value)
+    with pytest.raises(ValidationError):
+        RecipeStep.model_validate({"text": "x", "durationSeconds": value})
+
+
+def test_duration_json_schema_shape() -> None:
+    schema = RecipeStep.model_json_schema(by_alias=True)
+    prop = schema["properties"]["durationSeconds"]
