+    assert prop["anyOf"] == [{"type": "integer", "minimum": 1, "maximum": MAX}, {"type": "null"}]
+    assert "durationSeconds" not in schema.get("required", [])
+
+
+def test_duration_dump_alias() -> None:
+    assert RecipeStep(text="x", duration_seconds=90).model_dump(by_alias=True)["durationSeconds"] == 90
+
+
+def test_orm_column_definition() -> None:
+    col = RecipeInstruction.__table__.c.duration_seconds
+    assert col.type.__class__.__name__ == "Integer"
+    assert col.nullable is True
+    assert col.default is None
+    assert col.server_default is None
+
+
+def test_orm_built_from_model_dump(session) -> None:
+    step = RecipeStep(text="rest", duration_seconds=3661)
+    inst = RecipeInstruction(session=session, **step.model_dump())
+    assert inst.duration_seconds == 3661
+    assert inst.text == "rest"
+    inst_none = RecipeInstruction(session=session, **RecipeStep(text="a").model_dump())
+    assert inst_none.duration_seconds is None
+
+
+def test_handle_one_to_many_list_sets_and_clears(session) -> None:
+    step = RecipeStep(text="keep me", duration_seconds=5)
+    inst = RecipeInstruction(session=session, **step.model_dump())
+    session.add(inst)
+    session.commit()
+
+    payload = {**RecipeStep(id=step.id, text="keep me", duration_seconds=42).model_dump(), "id": str(inst.id)}
+    (updated,) = handle_one_to_many_list(session, "id", RecipeInstruction, [payload])
+    assert updated.duration_seconds == 42
+    assert updated.text == "keep me"
+
+    payload["duration_seconds"] = None
+    (updated,) = handle_one_to_many_list(session, "id", RecipeInstruction, [payload])
+    assert updated.duration_seconds is None
+    assert updated.text == "keep me"
