+<template>
+  <div v-if="isEditMode">
+    <v-number-input
+      :model-value="minutes"
+      :placeholder="$t('recipe.step-duration-minutes')"
+      :min="0"
+      :max="MAX_MINUTES"
+      :precision="0"
+      :hint="leftoverHint"
+      :persistent-hint="!!leftoverHint"
+      :hide-details="!leftoverHint"
+      density="compact"
+      variant="underlined"
+      inset
+      @keydown="preventMinus"
+      @update:model-value="onMinutesChange"
+    />
+  </div>
+  <span v-else-if="formatted">{{ formatted }}</span>
+</template>
+
+<script setup lang="ts">
+const MAX_SECONDS = 2147483647;
+const MAX_MINUTES = Math.floor(MAX_SECONDS / 60);
+
+const props = defineProps<{
+  modelValue: number | null;
+  isEditMode: boolean;
+}>();
+
+const emit = defineEmits<{
+  (e: "update:modelValue", value: number | null): void;
+}>();
+
+const i18n = useI18n();
+
+function toMinutes(seconds: number | null): number | null {
+  return seconds === null || seconds === undefined ? null : Math.floor(seconds / 60);
+}
+
+const minutes = ref<number | null>(toMinutes(props.modelValue));
+
+watch(() => props.modelValue, (value) => {
+  // Echo of our own emit: "0" minutes is emitted as null, but the input should keep showing 0
+  if (value === null && minutes.value === 0) {
+    return;
+  }
+  if (value !== null && minutes.value !== null && minutes.value * 60 === value) {
+    return;
+  }
+  minutes.value = toMinutes(value);
+});
+
+function onMinutesChange(value: number | null) {
+  const next = typeof value === "number" && Number.isFinite(value) ? Math.floor(value) : null;
+  if (next === minutes.value) {
+    return;
+  }
+
+  minutes.value = next;
+  emit("update:modelValue", next ? Math.min(next, MAX_MINUTES) * 60 : null);
+}
+
+function preventMinus(event: KeyboardEvent) {
+  if (event.key === "-") {
+    event.preventDefault();
+  }
+}
+
+function format(seconds: number): string {
+  const h = Math.floor(seconds / 3600);
+  const m = Math.floor((seconds % 3600) / 60);
+  const s = seconds % 60;
+  return [h && `${h}h`, m && `${m}m`, s && `${s}s`].filter(Boolean).join(" ");
+}
+
+const formatted = computed(() => (props.modelValue ? format(props.modelValue) : ""));
+
+const leftoverHint = computed(() => {
+  if (!props.modelValue || props.modelValue % 60 === 0) {
+    return "";
+  }
+  return i18n.t("recipe.step-duration-saved", { duration: format(props.modelValue) });
+});
+</script>
