+<template>
+  <div v-if="isEditMode">
+    <v-number-input
+      :model-value="minutes"
+      :min="0"
+      :max="MAX_MINUTES"
+      :precision="0"
+      :placeholder="$t('recipe.step-duration-placeholder')"
+      :hint="savedHint"
+      :persistent-hint="!!savedHint"
+      control-variant="hidden"
+      variant="underlined"
+      density="compact"
+      @keydown="onKeydown"
+      @update:model-value="onMinutes"
+    />
+  </div>
+  <span v-else-if="formatted">{{ formatted }}</span>
+</template>
+
+<script setup lang="ts">
+const props = defineProps<{ modelValue: number | null; isEditMode: boolean }>();
+const emit = defineEmits<{ (e: "update:modelValue", value: number | null): void }>();
+
+const { t } = useI18n();
+
+/** Largest whole number of minutes that still fits in the database's 2^31 - 1 seconds */
+const MAX_MINUTES = Math.floor((2 ** 31 - 1) / 60);
+
+function toMinutes(seconds: number | null): number | null {
+  return seconds ? Math.floor(seconds / 60) : null;
+}
+
+function toSeconds(value: number | null): number | null {
+  return value ? value * 60 : null;
+}
+
+const minutes = ref<number | null>(toMinutes(props.modelValue));
+
+watch(
+  () => props.modelValue,
+  (value) => {
+    // Our own emit (or a cleared 0) coming back shouldn't rewrite what the user sees
+    if ((value ?? null) === toSeconds(minutes.value)) {
+      return;
+    }
+    minutes.value = toMinutes(value);
+  },
+);
+
+function onMinutes(value: number | string | null | undefined) {
+  const next = value === null || value === undefined || value === "" ? null : Number(value);
+  const normalized = next === null || Number.isNaN(next) ? null : Math.min(Math.max(Math.trunc(next), 0), MAX_MINUTES);
+  // Blur and re-normalization echo the current value; only real edits replace the saved seconds
+  if (normalized === minutes.value) {
+    return;
+  }
+  minutes.value = normalized;
+  emit("update:modelValue", toSeconds(normalized));
+}
+
+function onKeydown(event: KeyboardEvent) {
+  if (event.key === "-") {
+    event.preventDefault();
+  }
+}
+
+function formatDuration(total: number): string {
+  const h = Math.floor(total / 3600);
+  const m = Math.floor((total % 3600) / 60);
+  const s = total % 60;
+  return [h && `${h}h`, m && `${m}m`, s && `${s}s`].filter(Boolean).join(" ");
+}
+
+const formatted = computed(() => (props.modelValue ? formatDuration(props.modelValue) : ""));
+
+const savedHint = computed(() =>
+  props.modelValue && props.modelValue % 60 !== 0
+    ? t("recipe.step-duration-saved", { duration: formatDuration(props.modelValue) })
+    : "",
+);
+</script>
